/**
 * Unmodified fixture Mod for the Fabric API assembled-composition test: a
 * plain Cordis plugin that imports ONLY the Fabric API contracts and
 * contributes an agent listener, a tool, prompt sections/variables, and a
 * human command. The assembly spec asserts every contribution through the
 * authoritative services and observes the agent listener through the real
 * event bus.
 */

export const name = 'fabric-api-fixture-mod'
export const inject = ['fabricAgent', 'fabricTools', 'fabricPrompt', 'fabricCommands']

const seen = []
globalThis.__fabricApiFixtureSeen = seen

export function apply(ctx) {
  ctx.fabricAgent.onStatus((agent, status) => {
    seen.push(`${agent.id}:${status}`)
  })

  ctx.fabricTools.register({
    name: 'mod-fixture-tool',
    description: 'fixture tool',
    parameters: { text: { type: 'string' } },
    output: {
      schema: { type: 'string' },
      render: (_args, value) => [{ type: 'text', text: value }],
    },
    async execute(args) {
      return args.text ?? ''
    },
  })

  ctx.fabricPrompt.section({ name: 'mod-fixture-section', order: -40, text: 'fixture section {{fixture_var}}' })
  ctx.fabricPrompt.context({ name: 'mod-fixture-context', order: 1, text: 'fixture context' })
  ctx.fabricPrompt.variable('fixture_var', () => 'fixture-value')

  ctx.fabricCommands.register({
    name: 'modfixture',
    description: 'fixture command',
    handler: () => ({ kind: 'success', text: 'fixture ok' }),
  })
}
